pred_cypher:
MATCH (n:River)-[:partOf]->(:DrainageBasin {name: "Lena basin"})
WHERE EXISTS { MATCH (n)-[:flowsInto]->(:Ocean {name: "Atlantic"}) }
RETURN n.name, n.length_km

CALL {
  MATCH (n:River)-[:flowsInto]->(:River {name: "Obukhovka"})
  RETURN n
  UNION
  MATCH (n:River)-[:partOf]->(:DrainageBasin)
  WHERE EXISTS { MATCH (n)-[:partOf]->(:DrainageBasin {name: "Tobol"}) }
  RETURN n
}
WITH DISTINCT n
RETURN count(n)
